def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    # Endgame: last round always defect
    if n >= 99:
        return 'D'

    # Exploit trigger: if we defected and opponent cooperated next round, they are forgiving.
    for i in range(n - 1):
        if my[i] == 'D' and op[i + 1] == 'C':
            return 'D'

    # High defection rate: if opponent has defected much more than cooperated, defect.
    op_def = sum(1 for a in op if a == 'D')
    op_c = n - op_def
    if n >= 8 and op_def > op_c + 1:
        return 'D'

    # Probing: if we haven't defected recently and opponent has been cooperating, probe.
    my_def_streak = 0
    for a in reversed(my):
        if a == 'D':
            my_def_streak += 1
        else:
            break

    op_c_streak = 0
    for a in reversed(op):
        if a == 'C':
            op_c_streak += 1
        else:
            break

    if my_def_streak == 0 and op_c_streak >= 5 and n >= 10:
        return 'D'

    last_op = op[-1]
    if last_op == 'D':
        opp_def_streak = 0
        for a in reversed(op):
            if a == 'D':
                opp_def_streak += 1
            else:
                break
        if opp_def_streak == 1:
            return 'C'
        if opp_def_streak >= 3:
            return 'C'
        return 'D'

    return 'C'
